package com.zhineng.platform.evaluation.selfevaluation;
import static org.junit.jupiter.api.Assertions.*;
import com.fasterxml.jackson.databind.ObjectMapper;import com.zhineng.platform.common.audit.OperationLogRepository;import com.zhineng.platform.common.database.*;import com.zhineng.platform.common.user.repository.UserRepository;import com.zhineng.platform.common.user.service.CurrentUserService;import com.zhineng.platform.evaluation.selfevaluation.dto.SelfEvaluationDtos.*;import com.zhineng.platform.evaluation.selfevaluation.repository.SelfEvaluationRepository;import com.zhineng.platform.evaluation.selfevaluation.service.SelfEvaluationService;import com.zhineng.platform.evaluation.selfevaluation.storage.SelfEvaluationStorage;
import java.nio.file.Path;import java.time.LocalDate;import java.util.*;import javax.sql.DataSource;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import org.springframework.boot.DefaultApplicationArguments;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.mock.env.MockEnvironment;import org.springframework.mock.web.MockMultipartFile;
class SelfEvaluationTest{
 @TempDir Path temp;
 @Test void taskFormMaterialAndRuleWarningClosedLoop()throws Exception{
  Fixture f=fixture();long version=seedIndicators(f.jdbc);long org=num(f.repo.orgs().get(0).get("id"));
  Map<String,Object>task=f.service.createTask(new TaskRequest("SELF-2026","2026自评",2026,"ANNUAL","2026-01-01","2026-12-31","测试",version,List.of(org)));long taskId=num(task.get("id"));task=f.service.publish(taskId);assertEquals("PUBLISHED",task.get("status"));
  long formId=num(((List<Map<String,Object>>)task.get("organizations")).get(0).get("id"));Map<String,Object>form=f.service.form(formId);Map<String,Object>entry=((List<Map<String,Object>>)form.get("entries")).get(0);long entryId=num(entry.get("id")),snapshot=num(entry.get("snapshot_id"));
  f.service.requirement(snapshot,new RequirementRequest(1,"pdf","证明",LocalDate.now().plusDays(1).toString()));
  Map<String,Object>run=f.service.runWarnings(taskId,org);assertEquals(1,((Number)run.get("warningCount")).intValue());
  MockMultipartFile file=new MockMultipartFile("file","证明材料.pdf","application/pdf","v1".getBytes());Map<String,Object>mat=f.service.upload(entryId,new MaterialRequest("证明材料","REPORT","说明",null,true,"2026-06-01"),file);assertEquals(1,((Number)mat.get("version_no")).intValue());
  String group=mat.get("version_group").toString();Map<String,Object>v2=f.service.upload(entryId,new MaterialRequest("证明材料新版","REPORT","替换",group,true,"2026-07-01"),new MockMultipartFile("file","证明材料新版.pdf","application/pdf","v2".getBytes()));assertEquals(2,((Number)v2.get("version_no")).intValue());assertEquals(2,f.service.materials(entryId).size());
  entry=f.repo.entry(entryId);f.service.saveEntry(entryId,new EntryRequest(9.0,"已完成年度重点工作并形成制度成果","COMPLETED",((Number)entry.get("row_version")).intValue()));
  form=f.service.submit(formId,new ReviewRequest(null,"提交"));form=f.service.review(formId,new ReviewRequest("RETURN","补充说明"));entry=f.repo.entry(entryId);f.service.saveEntry(entryId,new EntryRequest(9.5,"退回后已补充完整履职说明和相关依据","COMPLETED",((Number)entry.get("row_version")).intValue()));f.service.submit(formId,new ReviewRequest(null,"重提"));form=f.service.review(formId,new ReviewRequest("CONFIRM","确认完成"));assertEquals("COMPLETED",form.get("status"));
  run=f.service.runWarnings(taskId,org);assertEquals(0,((Number)run.get("warningCount")).intValue());
  new DatabaseMigrationRunner(f.ds).run(new DefaultApplicationArguments(new String[0]));assertEquals(1,f.jdbc.queryForObject("SELECT count(*) FROM schema_migrations WHERE version='13'",Integer.class));assertEquals(1,f.jdbc.queryForObject("PRAGMA foreign_keys",Integer.class));
 }
 private long seedIndicators(JdbcTemplate j){j.update("INSERT INTO indicator_systems(system_code,system_name,applicable_org_type,status)VALUES('SELF-SYS','自评指标','ALL','ACTIVE')");long s=j.queryForObject("SELECT id FROM indicator_systems WHERE system_code='SELF-SYS'",Long.class);j.update("INSERT INTO indicator_versions(system_id,evaluation_year,version_no,version_name,status)VALUES(?,2026,1,'2026发布版','PUBLISHED')",s);long v=j.queryForObject("SELECT id FROM indicator_versions WHERE system_id=?",Long.class,s);j.update("INSERT INTO indicator_items(version_id,indicator_level,indicator_code,indicator_name,weight,status)VALUES(?,1,'L1','一级',100,'ACTIVE')",v);long l1=j.queryForObject("SELECT id FROM indicator_items WHERE indicator_code='L1'",Long.class);j.update("INSERT INTO indicator_items(version_id,parent_id,parent_version_id,parent_level,indicator_level,indicator_code,indicator_name,weight,status)VALUES(?,?,?,?,2,'L2','二级',100,'ACTIVE')",v,l1,v,1);long l2=j.queryForObject("SELECT id FROM indicator_items WHERE indicator_code='L2'",Long.class);j.update("INSERT INTO indicator_items(version_id,parent_id,parent_version_id,parent_level,indicator_level,indicator_code,indicator_name,standard_score,weight,status)VALUES(?,?,?,?,3,'ZB-01','重点工作',10,100,'ACTIVE')",v,l2,v,2);return v;}
 private Fixture fixture()throws Exception{Path db=temp.resolve("self.sqlite");DataSource ds=new SQLiteDataSourceConfig().dataSource(new MockEnvironment().withProperty("app.database.path",db.toString()));new DatabaseMigrationRunner(ds).run(new DefaultApplicationArguments(new String[0]));JdbcTemplate jdbc=new JdbcTemplate(ds);SelfEvaluationRepository repo=new SelfEvaluationRepository(jdbc);SelfEvaluationService service=new SelfEvaluationService(repo,new CurrentUserService(new UserRepository(jdbc),"zhang.zhuren"),new OperationLogRepository(jdbc),new SelfEvaluationStorage(temp.resolve("storage").toString()),new ObjectMapper());return new Fixture(ds,jdbc,repo,service);}
 private long num(Object v){return((Number)v).longValue();}private record Fixture(DataSource ds,JdbcTemplate jdbc,SelfEvaluationRepository repo,SelfEvaluationService service){}
}
